sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
layout(color) uniform half4 color;
uniform float opacity;
float a(float2 p) { return float(image.eval(p).a); }
half4 main(float2 coord) {
    half4 col = image.eval(coord);
    float r = max(radius, 0.0);
    float r2 = r * 0.5;
    float2 d = float2(0.7071, 0.7071);
    float near = a(coord + float2(r, 0.0));
    near = max(near, a(coord - float2(r, 0.0)));
    near = max(near, a(coord + float2(0.0, r)));
    near = max(near, a(coord - float2(0.0, r)));
    near = max(near, a(coord + d * r));
    near = max(near, a(coord - d * r));
    near = max(near, a(coord + float2(d.x, -d.y) * r));
    near = max(near, a(coord - float2(d.x, -d.y) * r));
    near = max(near, a(coord + float2(r2, 0.0)));
    near = max(near, a(coord - float2(r2, 0.0)));
    near = max(near, a(coord + float2(0.0, r2)));
    near = max(near, a(coord - float2(0.0, r2)));
    near = max(near, a(coord + d * r2));
    near = max(near, a(coord - d * r2));
    near = max(near, a(coord + float2(d.x, -d.y) * r2));
    near = max(near, a(coord - float2(d.x, -d.y) * r2));
    float line = step(0.5, near) * (1.0 - step(0.5, float(col.a)));
    float oa = float(color.a) * opacity * line;
    half4 oc = half4(half3(float3(color.rgb) * oa), half(oa));
    return col + oc * (1.0 - col.a);
}
